import{_ as i,l as o,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"图数据库","description":"","frontmatter":{"title":"图数据库","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/graph-db.md","filePath":"cs/graph-db.md","lastUpdated":1789023840000}'),E={name:"cs/graph-db.md"};function c(B,a,_,u,A,m){const l=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="图数据库" tabindex="-1">图数据库 <a class="header-anchor" href="#图数据库" aria-label="Permalink to &quot;图数据库&quot;">​</a></h1><div class="epigraph"><p>点与边是一等存储：多跳邻接用指针或邻接表，不是反复自连接。查询语言是遍历与模式匹配，优化器面对的是路径基数爆炸。</p><footer>—— 据 Angles and Gutierrez 图数据库；Neo4j/属性图实践；关系递归 CTE 对照</footer></div><p><a href="/cs/wide-column-bigtable">上一课</a>靠行键编码图会把边挤进单元格。本课把图当模型：属性图（点边带属性）或 RDF 三元组。缺口是访问：关系用递归 CTE 表达传递闭包，计划弱；图引擎邻接索引让 \\(k\\) 跳更自然，但基数估计更差。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多对多：关系用连接表，图用边记录。遍历：从点沿边过滤。缺口是<strong>爆炸</strong>：度高时 \\(k\\) 跳组合爆炸，必须限制、最短路算法、或预计算。事务：改边与点的原子，隔离下的幻边（间隙锁的图版）难。分片：图切会切断边，跨片多跳即分布式 shuffle 的最坏形状。</p><p>索引：点标签、边类型、属性 B+。全文与向量可挂在点上，后课。</p><p><span class="marginnote">Angles and Gutierrez 综述。SPARQL vs Cypher 点名。本课不教查询语法课。递归 CTE 课是关系侧对照。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>OLTP 图：局部遍历、事务。分析图：批量 Pregel/Giraph，另引擎。混合：图投影从关系 nightly 建，新鲜度合同像 HTAP。</p><p>与 ART：内存图可用邻接数组。与 LSM：边日志追加，读放大在邻居列表 compaction。</p>',10)),(e(),n(h,null,{default:r(()=>[d(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E7%82%B9%22%5D%20--%3E%20E%5B%22%E9%82%BB%E6%8E%A5%E8%BE%B9%22%5D%0A%20%20E%20--%3E%20V2%5B%22%E9%82%BB%E7%82%B9%22%5D%0A%20%20Q%5B%22k%20%E8%B7%B3%E6%A8%A1%E5%BC%8F%22%5D%20--%3E%20CARD%5B%22%E8%B7%AF%E5%BE%84%E5%9F%BA%E6%95%B0%E7%88%86%E7%82%B8%22%5D%0A%20%20CUT%5B%22%E5%9B%BE%E5%88%86%E7%89%87%22%5D%20--%3E%20XSH%5B%22%E8%B7%A8%E7%89%87%E5%A4%9A%E8%B7%B3%20shuffle%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>优化器：选择率在相关邻居上独立假设更假。物理：变长邻接、CSR 只读分析。锁：点级或边级，死锁沿环路径——WFG 仍用。</p><p>关系对照：能用 SQL 几跳的不要上图库；图库赢在深度与变结构边类型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲时序压缩。也不把知识图谱训练当数据库课。向量 ANN 下一课之后。</p><p>后课默认：多跳 OLTP 用图引擎或限制深度的 CTE；分片图要认切边。时序数据库：时间为主键，压缩与保留策略第一。</p><p>图切分是 NP 难启发式，生产靠业务分区（租户）少切。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>属性图让遍历成为原生访问路径；k 跳基数难估。</li><li>分片切断边；分析图常用批量框架。</li><li>时序数据库下一课。</li><li>出处：Angles and Gutierrez；递归 CTE 对照。</li></ul>',9))])}const b=i(E,[["render",c]]);export{f as __pageData,b as default};
